<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{network:any}>();
const nodes=computed(()=>props.network?.nodes||[]);const lines=computed(()=>props.network?.lines||[]);
const capacity=computed(()=>nodes.value.reduce((s:any,n:any)=>s+Number(n.pd_kw||0),0));
const types=computed(()=>{const m=new Map<string,number>();for(const n of nodes.value){const label=n.node===1?'根节点':Number(n.pd_kw)>0?'有功负荷节点':'其他节点';m.set(label,(m.get(label)||0)+1)}return [...m.entries()]});
</script>
<template><section class="network-summary"><div class="network-stats"><div><span>节点</span><strong>{{network?nodes.length:'—'}}</strong><small>个</small></div><div><span>支路</span><strong>{{network?lines.length:'—'}}</strong><small>条</small></div><div><span>节点有功负荷</span><strong>{{network?capacity.toFixed(1):'—'}}</strong><small>kW</small></div><div><span>模型状态</span><strong class="state">{{network?'已应用':'待导入'}}</strong></div></div><div class="network-mini-grid"><article><header><h3>资源与负荷概览</h3><span>当前网络数据</span></header><div v-if="types.length" class="type-bars"><div v-for="[name,count] in types" :key="name"><span>{{name}}</span><i><b :style="{width:`${Math.min(100,Number(count)/Math.max(...types.map(t=>Number(t[1])))*100)}%`}"></b></i><em>{{count}}</em></div></div><div v-else class="empty-state">无网络对象，请从工具栏导入拓扑</div></article><article><header><h3>设备校核状态</h3><span>不替代模型校验</span></header><div class="check-list"><p><b :class="{ok:!!network}"></b>拓扑输入 {{network?'已加载':'待加载'}}</p><p><b :class="{ok:nodes.length>0}"></b>节点对象 {{nodes.length?'可编辑':'待补充'}}</p><p><b :class="{ok:lines.length>0}"></b>线路对象 {{lines.length?'可编辑':'待补充'}}</p></div></article></div></section></template>
<style scoped>
.network-summary{padding:14px 18px;background:#f4f6fa}.network-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.network-stats>div{background:#fff;border:1px solid #e1e8f1;border-radius:8px;padding:13px 15px}.network-stats span{display:block;color:#71819a;font-size:12px}.network-stats strong{font-size:25px;color:#245fd6;margin:7px 4px 0 0;display:inline-block}.network-stats small{color:#8492a4}.network-stats .state{font-size:18px}.network-mini-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:12px}.network-mini-grid article{background:#fff;border:1px solid #e1e8f1;border-radius:8px;padding:14px;min-height:150px}.network-mini-grid header{height:auto;background:transparent;border:0;padding:0;display:flex;justify-content:space-between}.network-mini-grid h3{font-size:14px;color:#233752;margin:0}.network-mini-grid header span{font-size:11px;color:#8492a4}.type-bars{margin-top:17px}.type-bars>div{display:grid;grid-template-columns:100px 1fr 30px;gap:8px;align-items:center;margin:12px 0}.type-bars span,.type-bars em{font-size:12px;color:#71819a;font-style:normal}.type-bars i{display:block;background:#edf2f8;height:8px;border-radius:5px}.type-bars b{height:8px;background:#4d83dd;display:block;border-radius:5px}.check-list{margin-top:14px}.check-list p{font-size:12px;color:#71819a;border-bottom:1px solid #edf0f5;padding:8px 0;margin:0}.check-list b{display:inline-block;width:8px;height:8px;border-radius:50%;background:#c5cfdd;margin-right:8px}.check-list b.ok{background:#31a56c}.empty-state{display:grid;place-items:center;height:90px;color:#9aa7b8;font-size:12px;border:1px dashed #dbe3ee;border-radius:6px;margin-top:14px}@media(max-width:850px){.network-stats{grid-template-columns:repeat(2,1fr)}.network-mini-grid{grid-template-columns:1fr}}
</style>
